using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;

namespace McpServer;

[McpServerToolType]
public class WeatherTools
{
    private readonly HttpClient _httpClient;

    // Constructor injection — the DI container provides HttpClient automatically
    public WeatherTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [McpServerTool, Description("Get current weather for a city")]
    public async Task<string> GetCurrentWeather(
        [Description("City name, e.g. 'Seattle'")] string city,
        [Description("Unit system: 'metric' or 'imperial'")] string units = "metric")
    {
        var response = await _httpClient.GetFromJsonAsync<WeatherResponse>(
            $"/data/2.5/weather?q={Uri.EscapeDataString(city)}&units={units}&appid=demo");

        if (response is null)
            return $"No weather data found for '{city}'.";

        return $"Weather in {city}: {response.Weather[0].Description}, " +
               $"Temp: {response.Main.Temp}°, Humidity: {response.Main.Humidity}%";
    }

    [McpServerTool, Description("Get 5-day weather forecast for a city")]
    public async Task<string> GetForecast(
        [Description("City name")] string city)
    {
        var response = await _httpClient.GetFromJsonAsync<ForecastResponse>(
            $"/data/2.5/forecast?q={Uri.EscapeDataString(city)}&units=metric&appid=demo");

        if (response is null)
            return $"No forecast data found for '{city}'.";

        var summary = response.List
            .GroupBy(f => DateOnly.FromDateTime(f.DtTxt))
            .Take(5)
            .Select(g => $"{g.Key}: {g.First().Main.Temp}°C, {g.First().Weather[0].Description}");

        return string.Join("\n", summary);
    }
}

// Response models
public record WeatherResponse(
    [property: JsonPropertyName("weather")] WeatherInfo[] Weather,
    [property: JsonPropertyName("main")] MainInfo Main);

public record ForecastResponse(
    [property: JsonPropertyName("list")] ForecastItem[] List);

public record ForecastItem(
    [property: JsonPropertyName("main")] MainInfo Main,
    [property: JsonPropertyName("weather")] WeatherInfo[] Weather,
    [property: JsonPropertyName("dt_txt")] DateTime DtTxt);

public record MainInfo(
    [property: JsonPropertyName("temp")] double Temp,
    [property: JsonPropertyName("humidity")] int Humidity);

public record WeatherInfo(
    [property: JsonPropertyName("description")] string Description);

using McpServer;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;

var builder = Host.CreateApplicationBuilder(args);

builder.Services
    .AddMcpServer()
    .WithStdioServerTransport()
    .WithToolsFromAssembly();

// Register a named HttpClient for WeatherTools via DI
builder.Services.AddHttpClient<WeatherTools>(client =>
{
    client.BaseAddress = new Uri("https://api.openweathermap.org");
    client.DefaultRequestHeaders.Add("Accept", "application/json");
});

await builder.Build().RunAsync();

